import{_ as i,l,o as e,c as s,v as t,p as h,x as r,d as n,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"Rowhammer 缓解","description":"","frontmatter":{"title":"Rowhammer 缓解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rowhammer-mitigations.md","filePath":"cs/rowhammer-mitigations.md","lastUpdated":1789023840000}'),c={name:"cs/rowhammer-mitigations.md"};function p(u,a,_,C,E,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="rowhammer-缓解" tabindex="-1">Rowhammer 缓解 <a class="header-anchor" href="#rowhammer-缓解" aria-label="Permalink to &quot;Rowhammer 缓解&quot;">​</a></h1><div class="epigraph"><p>反复敲击 DRAM 行可使相邻行比特翻转。缓解是目标刷新、ECC、隔离敏感页、降低访问强度。它把内存从「可靠存储」改回物理设备。</p><footer>—— Kim et al., Flipping Bits in Memory Without Accessing Them, ISCA 2014</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/spectre-mitigations">Spectre</a>是 CPU 前端。缺口是<strong>DRAM 扰动</strong>。本课讲翻转与缓解，不给打穿的操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隔离假设比特稳定。Rowhammer 打破。缺口：TRR、ECC、减少 clflush 一类高频访问、云共驻策略。</p><h3 id="ecc-不是万能" tabindex="-1">ECC 不是万能 <a class="header-anchor" href="#ecc-不是万能" aria-label="Permalink to &quot;ECC 不是万能&quot;">​</a></h3><p>可纠正错误有限；多比特仍可能过。</p><p><span class="marginnote">Kim et al. 2014。禁止 Rowhammer 利用教程。Flush+Reload 下一课是缓存侧信道经典。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述扰动物理。对策分层。下一课 Flush+Reload。</p>',12)),(e(),h(d,null,{default:r(()=>[m(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAMMER%5B%22%E9%AB%98%E9%A2%91%E8%A1%8C%E8%AE%BF%E9%97%AE%22%5D%20--%3E%20FLIP%5B%22%E9%82%BB%E8%A1%8C%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20FLIP%20--%3E%20MIT%5B%22TRR%20ECC%20%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬件可靠性进安全模型。缓存侧信道下一课不翻转比特，只测时间。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零利用。ECC 只能纠正有限翻转，不能当「内存已诚实」的证明。Flush+Reload 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Spectre 测微结构；Rowhammer 翻 DRAM 比特。</li><li>刷新、ECC、隔离页提高代价。</li><li>内存不是抽象可靠寄存器。</li><li>下一课 Flush+Reload。</li><li>出处：Kim et al., ISCA 2014。</li></ul>',8))])}const T=i(c,[["render",p]]);export{R as __pageData,T as default};
